typedef unsigned char u8;
typedef unsigned int u32;

u8 byte_data[8] = {0};
u8 *ptr = byte_data + 4;

// High Precedence: Cast Type (u32 *) binds before Pointer Arithmetic (+)
u32 data_word = *(u32 *)(ptr - 4);

// Cast applies to the immediate operand, before arithmetic
// (int) is higher precedence than multiplication *
long l_val = 0xFFFF;
int result_trap = (int)l_val * 5; // l_val cast to int, then multiplied

// Enforcing order: Cast applied to the result of the expression
int result_safe = (int)(l_val * 5); // Multiplication performed, then cast
